import numpy as np
import pandas as pd
from sklearn.metrics import (accuracy_score, average_precision_score,
                             confusion_matrix, f1_score, precision_score,
                             recall_score, roc_auc_score)
from sklearn.model_selection import GridSearchCV
from sklearn.pipeline import Pipeline

import config
from src import prep


def score(y_true, y_pred, y_score):
    """All the numbers we report, for the Unsafe class."""
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0, 1]).ravel()
    both_classes = len(np.unique(y_true)) == 2
    return {
        "roc_auc": roc_auc_score(y_true, y_score) if both_classes else np.nan,
        "avg_precision": average_precision_score(y_true, y_score) if both_classes else np.nan,
        "recall": recall_score(y_true, y_pred, zero_division=0),
        "precision": precision_score(y_true, y_pred, zero_division=0),
        "f1": f1_score(y_true, y_pred, zero_division=0),
        "accuracy": accuracy_score(y_true, y_pred),
        "tp": int(tp), "fp": int(fp), "fn": int(fn), "tn": int(tn),
    }


def save_rows(rows):
    """Add rows to the comparison table, replacing older rows for the same
    model and feature step."""
    new = pd.DataFrame(rows)
    config.RESULTS_DIR.mkdir(parents=True, exist_ok=True)
    if config.COMPARISON_PATH.exists():
        old = pd.read_csv(config.COMPARISON_PATH)
        keys = set(zip(new["model"], new["step"]))
        old = old[[key not in keys for key in zip(old["model"], old["step"])]]
        new = pd.concat([old, new], ignore_index=True)
    new = new.sort_values(["step", "model"]).reset_index(drop=True)
    new.to_csv(config.COMPARISON_PATH, index=False)
    return new


def run_feature_steps(model_name, estimator, param_grid, kind="scaled",
                      df=None, sampler=None, save=True, steps=None):
    """Tune and test one model on each feature step.

    model_name : label for the comparison table, for example "kNN".
    estimator  : an unfitted scikit-learn classifier.
    param_grid : settings to try, for example {"n_neighbors": [5, 15, 25]}.
    kind       : preparation style, see prep.make_preprocessor.
    sampler    : optional imbalanced-learn sampler such as SMOTE(). It is
                 applied inside the training folds only, never to the test set.

    Returns (results table, {step: fitted GridSearchCV}).
    """
    df = prep.load_table() if df is None else df
    train, test = prep.split_by_building(df)
    grid = {f"model__{name}": values for name, values in param_grid.items()}
    rows, fitted = [], {}

    for step in (steps or prep.FEATURE_STEPS):
        cols = prep.feature_columns(df, step)
        if not cols:
            print(f"{step}: no feature columns found, skipped")
            continue
        parts = [("prep", prep.make_preprocessor(train[cols], kind))]
        if sampler is not None:
            from imblearn.pipeline import Pipeline as SamplerPipeline
            pipe = SamplerPipeline(parts + [("sample", sampler), ("model", estimator)])
        else:
            pipe = Pipeline(parts + [("model", estimator)])

        search = GridSearchCV(pipe, grid, scoring="roc_auc", cv=prep.cv_folds(),
                              n_jobs=-1, refit=True)
        search.fit(train[cols], train[prep.LABEL], groups=train[prep.GROUP])

        y_score = search.predict_proba(test[cols])[:, 1]
        y_pred = search.predict(test[cols])
        best = {k.replace("model__", ""): v for k, v in search.best_params_.items()}
        row = {"model": model_name, "step": step, "n_features": len(cols),
               **score(test[prep.LABEL], y_pred, y_score),
               "cv_roc_auc": search.best_score_, "best_params": str(best)}
        rows.append(row)
        fitted[step] = search
        print(f"{model_name:22s} {step:20s} test ROC AUC {row['roc_auc']:.3f}   "
              f"recall {row['recall']:.3f}   precision {row['precision']:.3f}   {best}")

    results = pd.DataFrame(rows)
    if save and rows:
        save_rows(rows)
    return results, fitted


def run_baselines(df=None, save=True):
    """The two simple rules every model has to beat."""
    df = prep.load_table() if df is None else df
    train, test = prep.split_by_building(df)
    y = test[prep.LABEL]

    majority = int(train[prep.LABEL].mean() >= 0.5)
    always = np.full(len(test), majority)
    repeat = (test["f_prior_status"] == "UNSAFE").astype(int).to_numpy()

    rows = [
        {"model": "Baseline: majority class", "step": "0_baseline", "n_features": 0,
         **score(y, always, always.astype(float)), "cv_roc_auc": np.nan, "best_params": ""},
        {"model": "Baseline: repeat prior result", "step": "0_baseline", "n_features": 1,
         **score(y, repeat, repeat.astype(float)), "cv_roc_auc": np.nan, "best_params": ""},
    ]
    results = pd.DataFrame(rows)
    if save:
        save_rows(rows)
    return results
